'use strict';const M=LogViewerModel,U=OmniUI,$=id=>document.getElementById(id);let buffer=new M.LogBuffer(),sourceId=null,cursor=null,paused=false,inFlight=false,generation=0,stopped=false,exportText='';window.OMNI_PREVIEW=!window.omnibloomHost;let demoSequence=0;const demoLines=['Bloom Core ready','{"level":"info","username":"ExampleUser","access_token":"synthetic-secret","message":"Session accepted"}','Client 192.0.2.20 connected','Saved diagnostics to C:\\Users\\ExampleUser\\Documents\\debug.log','Worker retry scheduled','ExampleUser requested a status check'];function fixture(){const start=demoSequence,lines=(start?['Health check complete']:demoLines).map((text,i)=>({sequence:start+i,level:i===4?'warn':'info',time:'2026-11-03T12:00:00Z',text}));demoSequence+=lines.length;return{sourceId,streamId:'demo-'+sourceId,cursor:String(demoSequence),lines}}
function draw(){const previous=$('log-pane').scrollTop,rows=buffer.filtered($('level').value,$('query').value);$('lines').replaceChildren();for(const r of rows){const li=document.createElement('li');li.className='log-row level-'+r.level;for(const [cls,text]of [['log-time',r.time],['log-level',r.level.toUpperCase()],['log-text',r.text]]){const span=document.createElement('span');span.className=cls;span.textContent=text;li.append(span)}$('lines').append(li)}if(!rows.length){const li=document.createElement('li');li.textContent='No messages match this view.';$('lines').append(li)}$('count').textContent=rows.length+' shown · '+buffer.records.length+' buffered'+(buffer.dropped?' · '+buffer.dropped+' older omitted':'');$('export').disabled=!rows.length;if($('follow').checked&&!paused)$('log-pane').scrollTop=$('log-pane').scrollHeight;else $('log-pane').scrollTop=previous}
async function poll(){if(paused||inFlight||stopped||!sourceId)return;inFlight=true;const token=generation,requestedSource=sourceId;const timeout=setTimeout(()=>{if(token===generation&&inFlight)U.notify('The log reader is taking longer than expected. You can pause.')},8000);try{const result=await U.request('logs.read',{sourceId:requestedSource,cursor,maxLines:100,maxBytes:65536},fixture);if(token!==generation||paused||stopped)return;if(result?.sourceId!==requestedSource)throw Error('SOURCE_MISMATCH');const nextCursor=M.cursor(result.cursor);buffer.ingest(result);cursor=nextCursor;draw();$('unavailable').hidden=true;U.notify(window.OMNI_PREVIEW?'Preview messages · redacted locally.':'Following '+$('source').selectedOptions[0].textContent+'.')}catch(_){if(token===generation){$('unavailable').hidden=false;U.notify('Could not read logs. The current view is unchanged.')}}finally{clearTimeout(timeout);inFlight=false}}
async function load(){try{const values=M.sources(await U.request('logs.sources',{},()=>[{id:'hub',name:'Bloom Core'},{id:'omni',name:'Omni'},{id:'downloads',name:'Downloads'},{id:'master-control',name:'Master Control'}]));$('source').replaceChildren();for(const s of values){const o=document.createElement('option');o.value=s.id;o.textContent=s.name;$('source').append(o)}sourceId=values[0]?.id||null;$('unavailable').hidden=!sourceId;if(sourceId)await poll();else U.notify('No log sources are available.')}catch(_){$('unavailable').hidden=false;U.notify('Log sources are unavailable.')}}$('source').onchange=()=>{generation++;sourceId=$('source').value;cursor=null;buffer.clear();draw();poll()};$('level').onchange=draw;$('query').oninput=draw;$('follow').onchange=draw;$('pause').onclick=()=>{paused=!paused;generation++;$('pause').textContent=paused?'Resume':'Pause';U.notify(paused?'Paused. Buffered messages stay available.':'Following new messages.');if(!paused)poll()};$('clear').onclick=()=>{buffer.records=[];buffer.dropped=0;draw();U.notify('View cleared. Log files were not changed.')};$('retry').onclick=()=>sourceId?poll():load();$('export').onclick=()=>{exportText=buffer.export($('level').value,$('query').value);$('export-text').value=exportText;$('export-status').textContent='';U.modal('export-dialog')};$('save-export').onclick=async()=>{const button=$('save-export');if(button.disabled)return;button.disabled=true;try{exportText=exportText.split('\n').map(line=>buffer.redactor.line(line)).join('\n');$('export-text').value=exportText;const result=await U.request('logs.export',{name:'omnibloom-redacted-logs.txt',text:exportText},()=>{const blob=new Blob([exportText],{type:'text/plain;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='omnibloom-redacted-logs.txt';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);return{status:'pending'}});if(!['saved','cancelled','pending'].includes(result?.status))throw Error('INVALID_RESULT');$('export-status').textContent=result?.status==='saved'?'Redacted text saved.':result?.status==='cancelled'?'Save cancelled.':'Choose a destination to save the text.'}catch(_){$('export-status').textContent='Could not save the export. Try again.'}finally{button.disabled=false}};
window.handlePageController=a=>{if(document.activeElement!==$('log-pane'))return false;if(a==='circle'){U.focus($('pause'));return true}if(a==='down'||a==='up'){const pane=$('log-pane'),delta=a==='down'?160:-160,atEnd=a==='down'?pane.scrollTop+pane.clientHeight>=pane.scrollHeight-2:pane.scrollTop<=0;if(!atEnd){$('follow').checked=false;pane.scrollTop+=delta;return true}}return false};$('log-pane').addEventListener('wheel',()=>{$('follow').checked=false},{passive:true});const timer=setInterval(poll,2000);window.addEventListener('pagehide',()=>{stopped=true;generation++;clearInterval(timer);buffer.clear();buffer.redactor.names.clear();exportText='';$('export-text').value=''});load();U.focus($('pause'));
